INSERT INTO grade_restore_payload VALUES ('{"projects":[{"id":1175,"title":"造雪实验","description":"材料与步骤见正文。","author_id":"66020423-0000-0000-0000-000000000000","image_url":"https://spb-bp1n04y14st4y299.supabase.opentrust.net/storage/v1/object/public/project-images/covers/66020423-0000-0000-0000-000000000000/kejiao16a-ffb7a8ad8c5400fd4c22.jpg","category":"科学","difficulty":"easy","likes_count":0,"views_count":0,"created_at":"2026-09-18T10:20:22.351675+00:00","updated_at":"2026-10-25T11:16:44.322484+00:00","status":"approved","reviewed_by":null,"reviewed_at":null,"rejection_reason":null,"tags":["幼儿园小班","kejiao16a-src:幼儿园小班:034_造雪实验"],"sub_category_id":4,"difficulty_stars":1,"coins_count":0,"challenge_id":null,"reflection":null,"problem_statement":"kejiao16a; grade=幼儿园小班; folder=034_造雪实验; series=科教版","iterations":[],"steam_weights":{"A":10,"E":10,"M":5,"S":40,"T":5},"comments_count":0,"moderation_state":"approved","recommended_min_age":3,"recommended_max_age":null,"support_level":"guided","classification_status":"reviewed","classification_source":"manual","classification_reviewed_at":"2026-10-30T02:48:28.965355+00:00","classification_reviewed_by":"66020423-0000-0000-0000-000000000000","classification_revision":8,"video_url":"https://assets.steamx.cc/kejiao16a/幼儿园小班/034_造雪实验/video_1.mp4"},{"id":1183,"title":"荷塘月色","description":"把折拢的纸花轻放水面，观察花瓣吸水后逐渐展开。","author_id":"66020423-0000-0000-0000-000000000000","image_url":"https://spb-bp1n04y14st4y299.supabase.opentrust.net/storage/v1/object/public/project-images/covers/66020423-0000-0000-0000-000000000000/kejiao16a-135862fcb92d280da028.jpg","category":"科学","difficulty":"easy","likes_count":0,"views_count":0,"created_at":"2026-09-18T10:20:41.63068+00:00","updated_at":"2026-10-25T11:16:44.322484+00:00","status":"approved","reviewed_by":null,"reviewed_at":null,"rejection_reason":null,"tags":["幼儿园小班","kejiao16a-src:幼儿园小班:051_盛开的莲花"],"sub_category_id":null,"difficulty_stars":1,"coins_count":0,"challenge_id":null,"reflection":"水能沿纸中细小空隙进入，纸纤维吸水后发生膨胀和形变，折叠处随之舒展。纸的种类、折痕和厚度都会影响展开效果。","problem_statement":"kejiao16a; grade=幼儿园小班; folder=051_盛开的莲花; series=科教版","iterations":[],"steam_weights":{"A":10,"E":10,"M":5,"S":40,"T":5},"comments_count":0,"moderation_state":"approved","recommended_min_age":3,"recommended_max_age":null,"support_level":"guided","classification_status":"reviewed","classification_source":"manual","classification_reviewed_at":"2026-10-30T02:48:28.965355+00:00","classification_reviewed_by":"66020423-0000-0000-0000-000000000000","classification_revision":28,"video_url":"https://assets.steamx.cc/kejiao16a/幼儿园小班/051_盛开的莲花/video_1.mp4"},{"id":1200,"title":"平衡鹰","description":"将配套木质鹰与支架插合，找到鸟喙支撑位置，观察模型如何保持平衡。","author_id":"66020423-0000-0000-0000-000000000000","image_url":"https://spb-bp1n04y14st4y299.supabase.opentrust.net/storage/v1/object/public/project-images/covers/explore-reviewed-20260922/1200-e3072541099e2796.webp","category":"科学","difficulty":"easy","likes_count":0,"views_count":0,"created_at":"2026-09-18T10:21:25.562339+00:00","updated_at":"2026-10-25T12:24:15.027863+00:00","status":"approved","reviewed_by":null,"reviewed_at":null,"rejection_reason":null,"tags":["幼儿园中班","kejiao16a-src:幼儿园中班:014_平衡鹰"],"sub_category_id":4,"difficulty_stars":1,"coins_count":0,"challenge_id":null,"reflection":"模型能否平衡取决于重心与支撑位置的关系。配套鹰的形状让质量分布在鸟喙周围，合适的支撑位置可使重力的转动作用相互平衡；具体重心位置不能只凭外形精确判断。","problem_statement":"kejiao16a; grade=幼儿园中班; folder=014_平衡鹰; series=科教版","iterations":[],"steam_weights":{"A":10,"E":10,"M":5,"S":40,"T":5},"comments_count":0,"moderation_state":"approved","recommended_min_age":4,"recommended_max_age":null,"support_level":"guided","classification_status":"reviewed","classification_source":"manual","classification_reviewed_at":"2026-10-30T02:48:28.965355+00:00","classification_reviewed_by":"66020423-0000-0000-0000-000000000000","classification_revision":22,"video_url":"https://assets.steamx.cc/kejiao16a/幼儿园中班/014_平衡鹰/video_1.mp4"},{"id":1257,"title":"风向标","description":"用配套木板和转轴装出风向标，观察箭头和受风部件在气流中的运动。","author_id":"66020423-0000-0000-0000-000000000000","image_url":"https://spb-bp1n04y14st4y299.supabase.opentrust.net/storage/v1/object/public/project-images/covers/explore-reviewed-20260922/1257-4c49c24bcd514143.webp","category":"科学","difficulty":"easy","likes_count":0,"views_count":0,"created_at":"2026-09-18T10:23:56.747843+00:00","updated_at":"2026-10-25T12:49:51.715067+00:00","status":"approved","reviewed_by":null,"reviewed_at":null,"rejection_reason":null,"tags":["三年级","kejiao16a-src:三年级:019_风向标"],"sub_category_id":1,"difficulty_stars":1,"coins_count":0,"challenge_id":null,"reflection":"气流对不同形状和面积的部件产生不同作用，可使它们绕轴转动。这个套件用于观察气流与运动；未经校准的转速不能直接换算成风速。","problem_statement":"kejiao16a; grade=三年级; folder=019_风向标; series=科教版","iterations":[],"steam_weights":{"A":10,"E":10,"M":5,"S":40,"T":5},"comments_count":0,"moderation_state":"approved","recommended_min_age":6,"recommended_max_age":null,"support_level":"guided","classification_status":"reviewed","classification_source":"manual","classification_reviewed_at":"2026-10-30T02:48:28.965355+00:00","classification_reviewed_by":"66020423-0000-0000-0000-000000000000","classification_revision":28,"video_url":"https://assets.steamx.cc/kejiao16a/三年级/019_风向标/video_1.mp4"}],"materials":[{"id":4672,"project_id":1175,"material":"《造雪实验》对应实验材料包 1 套（需自行购买）","sort_order":0},{"id":4830,"project_id":1183,"material":"套件预裁纸花 4 朵","sort_order":0},{"id":4843,"project_id":1200,"material":"平衡鹰配套木质鹰形插片与支架拼板","sort_order":0},{"id":4868,"project_id":1257,"material":"配套编号木板（底板、支撑件、箭头、受风片、方向圆盘）","sort_order":0},{"id":4982,"project_id":1183,"material":"透明浅托盘 1 个","sort_order":1},{"id":4983,"project_id":1183,"material":"清水和倒水杯","sort_order":2},{"id":5040,"project_id":1257,"material":"配套长转轴、小轴与固定垫片","sort_order":1},{"id":5041,"project_id":1257,"material":"编辑观察补充：纸板扇","sort_order":2}],"steps":[{"id":6870,"project_id":1175,"title":"观看实验视频","description":"请准备好对应实验材料包，跟随本页视频完成操作。","image_url":null,"sort_order":0},{"id":7030,"project_id":1183,"title":"折拢花瓣","description":"把纸花放平，将各片花瓣依次向中心轻折，使花朵合拢。不要揉成紧实纸团。","image_url":null,"sort_order":0},{"id":7065,"project_id":1200,"title":"拼好支架","description":"将支架板沿配套槽位相互插合，压到位后放在桌面，检查支架站稳。","image_url":null,"sort_order":0},{"id":7110,"project_id":1257,"title":"搭好底座","description":"将标为2号的支撑件插进1号底板对应孔槽，核对支撑件的槽口方向与视频一致，使底板能平放。","image_url":null,"sort_order":0},{"id":7265,"project_id":1183,"title":"准备水盘","description":"把浅托盘放在平稳桌面，倒入足以让纸花漂浮的清水，留出不易溢水的空间。","image_url":null,"sort_order":1},{"id":7266,"project_id":1183,"title":"轻放纸花","description":"将折好的纸花正面向上轻放在水面，不按入水中。给不同纸花留出展开空间。","image_url":null,"sort_order":2},{"id":7267,"project_id":1183,"title":"观察并整理","description":"观察花瓣展开的先后和快慢，记录是否每一片都打开。结束后捞出纸花，倒掉托盘里的水并擦干桌面。","image_url":null,"sort_order":3},{"id":7295,"project_id":1200,"title":"拼好鹰身","description":"把鹰头与展开双翼的板件按对应槽位插合，检查板件没有明显偏斜或松脱。","image_url":null,"sort_order":1},{"id":7296,"project_id":1200,"title":"找到支撑位置","description":"一手托住鹰身，把鸟喙处轻放在支架顶端；缓慢松开托住的手，观察能否停稳。若滑落，接住后重新调整接触位置。","image_url":null,"sort_order":2},{"id":7297,"project_id":1200,"title":"轻触后观察","description":"模型停稳后轻触一侧再松手，观察是否摆动及能否重新停稳，不把它大幅拨离支点。","image_url":null,"sort_order":3},{"id":7380,"project_id":1257,"title":"组装箭头与受风片","description":"把配套轴穿过5号部件中间孔，两端用垫片定位；4号箭头也按对应孔位装轴。将受风片分别装到5号部件端部，卡入对应槽口。","image_url":null,"sort_order":1},{"id":7381,"project_id":1257,"title":"安装方向盘与支架","description":"将这些转动部件装到长转轴上，按配套结构装好7号方向圆盘及末端垫片，再把长轴组件插入底板和支撑件的孔中。轻拨检查是否能转动，不要将固定片压到夹死活动件。","image_url":null,"sort_order":2},{"id":7382,"project_id":1257,"title":"改变气流方向观察","description":"编辑观察：把底座放稳，用纸板从一侧轻轻扇风，观察箭头和受风片的运动。换一个来风方向，再记录箭头停下时指向哪边；此时先比较相对方向。","image_url":null,"sort_order":3}],"relations":[{"kit_id":"166a8842-e66d-566b-963c-849bb654ef0b","project_id":1175,"status":"candidate","preparation_status":"unknown","extras":[],"project_hash":null,"kit_revision":2,"sort_order":1175,"evidence":{"basis":"exact_grade_source_and_current_supplier_directory","reviewedAt":"2026-10-30","sourceTag":"kejiao16a-src:幼儿园小班:034_造雪实验","cata